#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    if (books.empty()) {
        return books.size(); // no match
    }

    long long lastIndex = -1;

    #pragma omp parallel for reduction(max:lastIndex)
    for (long long i = 0; i < static_cast<long long>(books.size()); ++i) {
        if (books[static_cast<std::size_t>(i)].pages < 100) {
            if (i > lastIndex) {
                lastIndex = i;
            }
        }
    }

    return (lastIndex >= 0) ? static_cast<std::size_t>(lastIndex) : books.size();
}
